function change(amount, till) {
  const handed = [];
  for (const [value, count] of till) {
    for (let used = 0; used < count && amount >= value; used++) {
      handed.push(value);
      amount -= value;
    }
  }
  return amount === 0 ? handed.join("+") : `stuck with ${amount} left`;
}

