function changeCounts(amount) {
  const parts = [];
  for (const value of naira) {
    const count = Math.floor(amount / value);
    if (count > 0) {
      parts.push(`${value}x${count}`);
      amount -= count * value;
    }
  }
  return parts.join(" ");
}

