const jobs = [
  { id: "A", minutes: 25, deadline: 40 },
  { id: "B", minutes: 30, deadline: 60 },
  { id: "C", minutes: 10, deadline: 20 },
];

function plan(jobs) {
  const sorted = jobs.toSorted((a, b) => a.deadline - b.deadline);
  let time = 0;
  let worst = 0;
  for (const job of sorted) {
    time += job.minutes;
    worst = Math.max(worst, time - job.deadline);
  }
  return { order: sorted.map((j) => j.id).join(""), worst };
}

const { order, worst } = plan(jobs);
console.log(order, worst);

