function fewest(amount, values) {
  const best = [0];
  for (let a = 1; a <= amount; a++) {
    best[a] = Infinity;
    for (const v of values) {
      if (v <= a && best[a - v] + 1 < best[a]) best[a] = best[a - v] + 1;
    }
  }
  return best[amount] === Infinity ? -1 : best[amount];
}

console.log(fewest(800, [500, 400, 100]), fewest(1200, [500, 400, 100]), fewest(800, [750, 400]), fewest(50, [750, 400]));

